// Java config: one servlet mapped to every request
public class WebAppInitializer
        extends AbstractAnnotationConfigDispatcherServletInitializer {
    protected Class<?>[] getServletConfigClasses() { return new Class<?>[]{ WebConfig.class }; }
    protected String[] getServletMappings() { return new String[]{"/"}; }
}

@RestController
class OrderController {
    @GetMapping("/orders/{id}")
    Order get(@PathVariable long id) { return repo.find(id); }
}

@WebServlet("/*")
public class FrontController extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse res)
            throws IOException, ServletException {
        if (!Auth.check(req)) { res.sendError(401); return; }      // shared behaviour
        Command cmd = RequestHelper.commandFor(req);               // dispatcher
        req.getRequestDispatcher(cmd.execute(req, res)).forward(req, res);   // view
    }
    protected void doPost(HttpServletRequest req, HttpServletResponse res)
            throws IOException, ServletException { doGet(req, res); }
}

@Bean
RouterFunction<ServerResponse> orders(OrderHandler h) {
    return route().GET("/orders/{id}", accept(TEXT_PLAIN), h::get).build();
}

@Bean
WebFilter authFilter() {
    return (exchange, chain) -> authorized(exchange)
            ? chain.filter(exchange)
            : exchange.setComplete();          // short-circuit
}

